candidate=parse('compose.yaml');assert set(candidate)=={'services','volumes','networks'}
assert set(candidate['services'])=={'db','worker'}
assert all(set(s)<={'image','volumes','networks'} for s in candidate['services'].values())
original=(root/'compose.yaml').read_bytes()
volume='tenant-store-'+secrets.token_hex(4);network='tenant-net-'+secrets.token_hex(4)
for project in ('blue-teaching','green-teaching'):
    model=native(['compose.yaml'],variables={'DB_VOLUME':volume,'SHARED_NETWORK':network},project=project)
    assert model['name']==project and set(model['services'])=={'db','worker'}
    assert set(model['volumes'])=={'dbdata','cache'} and set(model['networks'])=={'shared','default'}
    external=model['volumes']['dbdata'];assert external['name']==volume and external['external'] is True
    assert set(external)<={'name','external'}
    local=model['volumes']['cache'];assert local['name']==project+'_cache' and not local.get('external',False)
    shared=model['networks']['shared'];assert shared['name']==network and shared['external'] is True
    assert not shared.get('driver') and not shared.get('driver_opts')
    default=model['networks']['default'];assert default['name']==project+'_default' and not default.get('external',False)
    for name,source,target,net,image in [('db','dbdata','/var/lib/postgresql/data','shared','postgres:16-alpine'),('worker','cache','/cache','default','busybox:1.36')]:
        service=model['services'][name];assert service['image']==image and set(service['networks'])=={net}
        assert not service.get('ports')
        mounts=service['volumes'];assert len(mounts)==1 and mounts[0]['type']=='volume' and mounts[0]['source']==source and mounts[0]['target']==target
assert (root/'compose.yaml').read_bytes()==original

# Verify each mandatory variable independently, absent and explicitly empty.
for missing in ('DB_VOLUME','SHARED_NETWORK'):
    for empty in (False,True):
        env={k:v for k,v in os.environ.items() if not k.upper().startswith(('DOCKER_','COMPOSE_')) and k not in ('DB_VOLUME','SHARED_NETWORK')}
        env.update(DOCKER_HOST='tcp://127.0.0.1:1',COMPOSE_DISABLE_ENV_FILE='true')
        env.update(DB_VOLUME=volume,SHARED_NETWORK=network)
        if empty:env[missing]=''
        else:env.pop(missing)
        proc=subprocess.run(['docker-compose','--project-name','blue-teaching','--project-directory',str(root),'-f','compose.yaml','config','--format','json'],cwd=root,env=env,capture_output=True,text=True,timeout=5)
        assert proc.returncode!=0,'missing/empty mandatory variable must not silently use a fallback resource name: '+missing
